    private readonly Dictionary<string, object> sectionElementCache = new(StringComparer.Ordinal);

    private T ResolveSectionElement<T>(FrameworkElement sectionHost, string elementName)
        where T : class
    {
        string cacheKey = $"{sectionHost.Name}:{elementName}";
        if (sectionElementCache.TryGetValue(cacheKey, out object? cached))
        {
            return (T)cached;
        }

        // The contact's page may stand beside a chat (MainWindow.ChatContactInfo.cs): out of the
        // Contacts tree, its elements are found from the page itself.
        object? resolved = sectionHost.FindName(elementName) ?? movedContactPage?.FindName(elementName);
        if (resolved is not T typed)
        {
            throw new InvalidOperationException($"Could not resolve '{elementName}' from section host '{sectionHost.Name}'.");
        }

        sectionElementCache[cacheKey] = typed;
        return typed;
    }

